"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import { useRouter } from "next/navigation";
import { ChevronDown, CreditCard, LogOut, Settings } from "lucide-react";

const menuItemClass =
  "flex items-center w-full h-11.5 py-0 px-3.5 border-0 rounded-[12px] gap-3 text-[15px] font-normal text-left bg-transparent text-[var(--foreground,var(--color-globals-color-65))] cursor-pointer css-hover:bg-[var(--surface,var(--color-globals-background-70))]";

export function AccountMenu({
  name,
  email,
  signOut,
}: {
  name: string | null;
  email: string;
  signOut: () => Promise<void>;
}) {
  const [open, setOpen] = useState(false);
  const root = useRef<HTMLDivElement>(null);
  const trigger = useRef<HTMLButtonElement>(null);
  const router = useRouter();
  const focusFrame = useRef<number | undefined>(undefined);
  useEffect(
    () => () => {
      if (focusFrame.current !== undefined)
        cancelAnimationFrame(focusFrame.current);
    },
    [],
  );
  const close = useCallback(() => {
    setOpen(false);
    trigger.current?.focus({ preventScroll: true });
    // Pointer defaults can move focus again after the outside-click handler.
    if (focusFrame.current !== undefined)
      cancelAnimationFrame(focusFrame.current);
    focusFrame.current = requestAnimationFrame(() =>
      trigger.current?.focus({ preventScroll: true }),
    );
  }, []);
  useEffect(() => {
    if (!open) return;
    const outside = (event: PointerEvent) => {
      if (!root.current?.contains(event.target as Node)) close();
    };
    const escape = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        event.preventDefault();
        close();
      }
    };
    document.addEventListener("pointerdown", outside);
    document.addEventListener("keydown", escape);
    root.current?.querySelector<HTMLButtonElement>("[role=menuitem]")?.focus();
    return () => {
      document.removeEventListener("pointerdown", outside);
      document.removeEventListener("keydown", escape);
    };
  }, [open, close]);
  return (
    <div
      ref={root}
      className="workspace-account relative"
      onKeyDown=[REDACTED_SECRET]
        if (
          !open ||
          !["ArrowDown", "ArrowUp", "Home", "End"].includes(event.key)
        )
          return;
        event.preventDefault();
        const items = Array.from(
          root.current?.querySelectorAll<HTMLButtonElement>(
            "[role=menuitem]",
          ) ?? [],
        );
        const index = items.indexOf(
          document.activeElement as HTMLButtonElement,
        );
        items[
          event.key === "Home"
            ? 0
            : event.key === "End"
              ? items.length - 1
              : (index + (event.key === "ArrowDown" ? 1 : -1) + items.length) %
                items.length
        ]?.focus();
      }}
    >
      <button
        ref={trigger}
        type="button"
        className="workspace-account-trigger inline-flex items-center shrink-0 [border:1px_solid_var(--border,_var(--color-globals-border-63))] rounded-full [background:var(--card,_var(--color-globals-background-64))] text-[var(--foreground,_var(--color-globals-color-65))] h-11 [padding:0_12px_0_5px] gap-2 cursor-pointer"
        aria-label="Account menu"
        aria-haspopup="menu"
        aria-expanded={open}
        onClick={() => (open ? close() : setOpen(true))}
        onKeyDown=[REDACTED_SECRET]
          if (!open && ["ArrowDown", "ArrowUp"].includes(event.key)) {
            event.preventDefault();
            setOpen(true);
          }
        }}
      >
        <span className="workspace-avatar grid place-items-center w-8 h-8 text-[14px] [border:1px_solid_color-mix(in_srgb,_var(--accent)_24%,_transparent)] rounded-[50%] [background:var(--avatar-background)] text-[var(--color-globals-card-3)] font-semibold">
          {(name?.trim() || email).slice(0, 1).toUpperCase()}
        </span>
        <ChevronDown size={14} strokeWidth={2.4} aria-hidden="true" />
      </button>
      {open && (
        <div
          role="menu"
          aria-label="Account"
          className="workspace-account-menu absolute [top:calc(100%_+_10px)] right-0 z-[100] w-72.5 max-w-[calc(100vw_-_40px)] p-2 [border:1px_solid_var(--border,_var(--color-globals-border-63))] rounded-[20px] [background:var(--card,_var(--color-globals-background-64))] shadow-[0_24px_60px_var(--color-globals-box-shadow-68)]"
          onBlur={(event) => {
            if (!root.current?.contains(event.relatedTarget as Node)) close();
          }}
        >
          <div className="workspace-account-heading flex flex-col gap-1.5 [padding:12px_14px_14px] mb-2 border-b border-dotted border-separator">
            <span className="workspace-mono-label [font-family:var(--font-mono)] text-[10px] font-normal tracking-[0.16em] text-[var(--muted-foreground,_var(--color-globals-color-62))]">
              SIGNED IN AS
            </span>
            <span
              className="workspace-account-email overflow-hidden text-ellipsis whitespace-nowrap text-[15px] font-semibold"
              title={email}
            >
              {email}
            </span>
          </div>
          <button
            type="button"
            className={menuItemClass}
            role="menuitem"
            onClick={() => {
              close();
              router.push("/settings");
            }}
          >
            <Settings
              className="shrink-0"
              size={18}
              strokeWidth={1.8}
              aria-hidden="true"
            />
            Settings
          </button>
          <button
            type="button"
            className={menuItemClass}
            role="menuitem"
            onClick={() => {
              close();
              router.push("/pricing");
            }}
          >
            <CreditCard
              className="shrink-0"
              size={18}
              strokeWidth={1.8}
              aria-hidden="true"
            />
            Pricing
          </button>
          <form action={signOut} onSubmit={close}>
            <button type="submit" className={menuItemClass} role="menuitem">
              <LogOut
                className="shrink-0"
                size={18}
                strokeWidth={1.8}
                aria-hidden="true"
              />
              Sign out
            </button>
          </form>
        </div>
      )}
    </div>
  );
}
